package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TarArchiveEntry_isDirectory_TriageGen0Test {

    private static final byte LF_DIR = 0x05; // Standard TAR link flag for directory
    private static final byte LF_REG = 0x00; // Standard TAR link flag for regular file

    @Test
    public void testIsDirectory_WithFileObjectTrue() {
        // Case: file != null and file.isDirectory() returns true
        File mockFile = mock(File.class);
        when(mockFile.isDirectory()).thenReturn(true);

        TarArchiveEntry entry = new TarArchiveEntry(mockFile, "testDir");
        assertTrue("Should return true when file.isDirectory() is true", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_WithFileObjectFalse() {
        // Case: file != null and file.isDirectory() returns false
        File mockFile = mock(File.class);
        when(mockFile.isDirectory()).thenReturn(false);

        TarArchiveEntry entry = new TarArchiveEntry(mockFile, "testFile");
        assertFalse("Should return false when file.isDirectory() is false", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_WithLinkFlagDir() {
        // Case: file == null and linkFlag == LF_DIR
        TarArchiveEntry entry = new TarArchiveEntry("testDir", LF_DIR);
        assertTrue("Should return true when linkFlag is LF_DIR", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_WithNameEndingWithSlash() {
        // Case: file == null, linkFlag != LF_DIR, and name ends with "/"
        // Note: We use a constructor that doesn't set linkFlag to a directory flag
        TarArchiveEntry entry = new TarArchiveEntry("testDir/");
        assertTrue("Should return true when name ends with '/'", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_AllFalse() {
        // Case: file == null, linkFlag != LF_DIR, and name does not end with "/"
        TarArchiveEntry entry = new TarArchiveEntry("testFile");
        assertFalse("Should return false when all conditions fail", entry.isDirectory());
    }

    @Test
    public void testIsDirectory_WithLinkFlagNotDirAndNoSlash() {
        // Case: file == null, linkFlag is a regular file, and name does not end with "/"
        TarArchiveEntry entry = new TarArchiveEntry("testFile", LF_REG);
        assertFalse("Should return false when linkFlag is not DIR and name has no trailing slash", entry.isDirectory());
    }
}
